package com.dualphone.controller.transport.protocol

import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.security.SecureRandom
import java.util.UUID

/**
 * Lightweight pairing / session authentication over TCP.
 * Pairing token is a random 32-bit value generated by the receiver.
 * Session id is a random 32-bit value assigned after successful auth.
 */
object SessionAuth {
    private val random = SecureRandom()

    fun generatePairingToken(): Int = random.nextInt()
    fun generateSessionId(): Int = random.nextInt().let { if (it == 0) 1 else it }

    // AUTH_REQUEST: version(1) type(1) pairingToken(4) deviceNameLen(1) name(bytes) padding to fixed
    // We use a fixed 64-byte frame for simplicity.
    const val AUTH_FRAME_SIZE = 64

    fun encodeAuthRequest(pairingToken: Int, deviceName: String): ByteArray {
        val buf = ByteBuffer.allocate(AUTH_FRAME_SIZE).order(ByteOrder.LITTLE_ENDIAN)
        buf.put(BinaryPacketProtocol.PROTOCOL_VERSION)
        buf.put(BinaryPacketProtocol.PacketType.AUTH_REQUEST.code)
        buf.putInt(pairingToken)
        val nameBytes = deviceName.toByteArray(Charsets.UTF_8).take(48)
        buf.put(nameBytes.size.toByte())
        buf.put(nameBytes.toByteArray())
        return buf.array()
    }

    data class AuthRequest(val pairingToken: Int, val deviceName: String)

    fun decodeAuthRequest(data: ByteArray): AuthRequest? {
        if (data.size < 8) return null
        val buf = ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN)
        val version = buf.get()
        if (version != BinaryPacketProtocol.PROTOCOL_VERSION) return null
        val type = buf.get()
        if (type != BinaryPacketProtocol.PacketType.AUTH_REQUEST.code) return null
        val token = buf.int
        val nameLen = buf.get().toInt() and 0xFF
        if (nameLen > 48 || buf.remaining() < nameLen) return null
        val nameBytes = ByteArray(nameLen)
        buf.get(nameBytes)
        return AuthRequest(token, String(nameBytes, Charsets.UTF_8))
    }

    // AUTH_RESPONSE: version type sessionId status(0=ok,1=fail) udpPort(2)
    fun encodeAuthResponse(sessionId: Int, accepted: Boolean, udpPort: Int): ByteArray {
        val buf = ByteBuffer.allocate(AUTH_FRAME_SIZE).order(ByteOrder.LITTLE_ENDIAN)
        buf.put(BinaryPacketProtocol.PROTOCOL_VERSION)
        buf.put(BinaryPacketProtocol.PacketType.AUTH_RESPONSE.code)
        buf.putInt(sessionId)
        buf.put(if (accepted) 0 else 1)
        buf.putShort(udpPort.toShort())
        return buf.array()
    }

    data class AuthResponse(val sessionId: Int, val accepted: Boolean, val udpPort: Int)

    fun decodeAuthResponse(data: ByteArray): AuthResponse? {
        if (data.size < 10) return null
        val buf = ByteBuffer.wrap(data).order(ByteOrder.LITTLE_ENDIAN)
        val version = buf.get()
        if (version != BinaryPacketProtocol.PROTOCOL_VERSION) return null
        val type = buf.get()
        if (type != BinaryPacketProtocol.PacketType.AUTH_RESPONSE.code) return null
        val sessionId = buf.int
        val status = buf.get()
        val udpPort = buf.short.toInt() and 0xFFFF
        return AuthResponse(sessionId, status.toInt() == 0, udpPort)
    }

    fun encodeDisconnect(sessionId: Int): ByteArray {
        val buf = ByteBuffer.allocate(AUTH_FRAME_SIZE).order(ByteOrder.LITTLE_ENDIAN)
        buf.put(BinaryPacketProtocol.PROTOCOL_VERSION)
        buf.put(BinaryPacketProtocol.PacketType.DISCONNECT.code)
        buf.putInt(sessionId)
        return buf.array()
    }
}
